import numpy as np

def make_prices(n=750, seed=21, mu=0.0003, sigma=0.012):
    """n + 1 daily closes from 100: daily log returns mu + sigma * noise."""
    rng = np.random.default_rng(seed)
    r = mu + sigma * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def make_regime_prices(n=500, seed=11, calm=0.006, wild=0.02):
    """n + 1 closes: calm for the first half, wild for the second."""
    rng = np.random.default_rng(seed)
    sig = np.where(np.arange(n) < n // 2, calm, wild)
    r = 0.0002 + sig * rng.standard_normal(n)
    return np.round(100 * np.exp(np.concatenate([[0.0], np.cumsum(r)])), 4).tolist()

def log_returns(prices):
    """Daily log returns: entry t is ln(P[t+1] / P[t])."""
    p = np.asarray(prices, dtype=float)
    return np.round(np.diff(np.log(p)), 8).tolist()

