def dead_zone_label(returns, h, vol_window, k):
    r = np.asarray(returns, dtype=float)
    out = []
    for t in range(vol_window - 1, len(r) - h):
        s = r[t - vol_window + 1:t + 1].std(ddof=1)
        f = r[t + 1:t + h + 1].sum()
        b = k * s * np.sqrt(h)
        out.append(1 if f > b else (-1 if f < -b else 0))
    return out
